"""Cold-read the actual native finished-board Pad and export its local geometry."""
from pathlib import Path
import hashlib,json
import FreeCAD as A,Part
H=Path(__file__).resolve().parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
p=H/'SingleFlangePlacement.FCStd';d=A.openDocument(str(p));body=d.getObject('PCB');pad=d.getObject('FinishedPCB');assert pad.Length==1 and d.getObject('BoardOutlineAndHoles').FullyConstrained
shape=body.Shape.copy();shape.transformShape(body.Placement.inverse().toMatrix());b=shape.optimalBoundingBox(False,False);bounds=[getattr(b,n)for n in('XMin','YMin','ZMin','XMax','YMax','ZMax')];assert max(abs(a-b)for a,b in zip(bounds,[-41,-13,0,41,13,1]))<1e-6,bounds
assert shape.isValid()and len(shape.Solids)==1;out=H/'FinishedPCB_local.step';shape.exportStep(str(out));cold=Part.Shape();cold.read(str(out));assert not cold.isNull()and cold.isValid()and len(cold.Solids)==1 and abs(cold.Volume-shape.Volume)<1e-6
m=json.loads((H/'mcad.json').read_text());r={'status':'pass: native parametric finished1mmPCB, independent coldSTEP readback','board_sha256':m['board_sha256'],'native_source':str(p),'native_source_sha256':sha(p),'Body':'PCB','Tip':'FinishedPCB','profile':'BoardOutlineAndHoles','fully_constrained_profile':True,'Pad_Length_mm':1,'STEP':str(out),'STEP_sha256':sha(out),'STEP_bounds_local_mm':bounds,'solid_count':1,'volume_mm3':cold.Volume,'proper_local_to_product_matrix4':[[1,0,0,0],[0,0,-1,-25.952],[0,1,0,0],[0,0,0,1]],'native_outline_and_8drills':True,'copper_mask_or_process_qualification':False,'note':'This is the actual PCB finished envelope from its native outline/drills, not the raw KiCad material-only0.91mm FR4 export. Do not substitute component box proxies.'};(H/'finished-board.json').write_text(json.dumps(r,indent=2)+'\n')
m['finished_board_local_STEP']='hardware/pcb/evt1/single-flange-study/FinishedPCB_local.step';m['finished_board_local_STEP_sha256']=sha(out);m['finished_board_native']='hardware/pcb/evt1/single-flange-study/SingleFlangePlacement.FCStd';m['finished_board_native_sha256']=sha(p);m['finished_board_binding_sha256']=sha(H/'finished-board.json');m['mechanical_native_sha256']=sha(p);m['mechanical_STEP_sha256']=sha(H/'SingleFlangePlacement.step');(H/'mcad.json').write_text(json.dumps(m,indent=2)+'\n');print(json.dumps({k:r[k]for k in('status','STEP_sha256','STEP_bounds_local_mm','volume_mm3')}))
